export type Stop = { kind: string; place: string; was: string | null; now: string; gap: string };
export type Call = {
    no: number; grabbed: string; fare: string; rush: boolean;
    color: { tone: 'honey' | 'normal'; text: string };
    nodes: [number, number]; p: string; d: string; headAt: [string, string];
    stops: [Stop, Stop];
    buf: { tone: 'ok' | 'bad' | 'plain'; text: string }[];
    memo: string;
    site: { p: [string, string, string]; d: [string, string, string] };
    now: number; stamp: string[];
    /** 🔴 **실측이 아닌 칸이 있으면 여기에 근거를 적는다** — 화면이 「시늉」 배지로 말한다 (규칙 ⑤-2) */
    mock?: string;
    /**
     * 🚚 **이 콜이 부르는 차종** — 내 차종이 아니다.
     * 🔴 **단가가 여기서 나온다** — `PricingEngine` 이 «적정 금액 = 거리 × **차종 단가** ×
     *    (1 − 수수료율)» 로 센다. 내 차종은 콜에 값이 없을 때 쓰는 폴백일 뿐이다.
     */
    vehicle: string;
    /**
     * 💸 **그 콜의 알선 수수료율** — 배차망 화면에서 긁은 값(`commissionRate`).
     * 🔴 **콜마다 다르다.** 목업이 오래 「23%」를 고정 문자열로 적어 두어 어느 콜을
     *    펼쳐도 같은 값이었다 — 화면이 조용히 거짓말을 한 자리다.
     * ⚠️ `"*%"`(모름)도 온다 — 그때는 그대로 적는다. 지어내지 않는다 (규칙 ④)
     */
    commission: string;
    /**
     * 📦 **배차망이 말한 품목** (`itemDescription`) — 「서류봉투」·「쇼핑백 2개」.
     *
     * 🔴 **적재 계산의 근거가 아니다.** 그것은 통화·신고로 채워지는 `CargoReport`
     *    (`unit`·`quantity`·`handling`)이고, 헤더의 `📦 90/100` 이 그 결과다.
     *    여기는 «배차망이 뭐라고 했나»일 뿐 — **신고가 오면 그것이 이긴다.**
     */
    item?: string;
    /**
     * 🎨 **몇 번 콜인가 — 색의 입력이다**.
     *
     * 🔴 전에는 목록이 **자기 인덱스**로 색을 정했다. 3콜 판에서는 목록이 [1,2,3] 순이라
     *    우연히 맞았지만, 시나리오 판은 콜이 [2,3,1] 차례로 붙어 **첫 장면의 목록 0번째가
     *    callNo 2** 다 — 지도는 2로, 목록은 1로 칠해 **같은 콜이 두 색**이 됐다
     *    (기사님: *"지금 색이 지도랑 리스트가 같지 않아"*).
     * 🔴 색이 곧 결정이다 (규칙 ⑤-3). 입력을 하나로 못박는다 (규칙 ③).
     */
    callNo: number;
};

